// ============================================================
// VALIDATE & PARSE incoming multipart/form-data
// ============================================================
const items = $input.all();
const body = items[0]?.json?.body || items[0]?.json || {};
const binary = items[0]?.binary || {};

// --- Extract text fields ---
const name = (body.name || '').trim();
const description = (body.description || '').trim();
const regularPrice = (body.regular_price || '').toString().trim();
const salePrice = (body.sale_price || '').toString().trim();
const sku = (body.sku || '').toString().trim();
const stockMode = (body.stock_mode || 'in_stock').trim();
const quantity = body.quantity ? parseInt(body.quantity) : null;
const galleryCount = parseInt(body.gallery_count) || 0;

// Parse categories
let categories = [];
if (Array.isArray(body.categories)) {
  categories = body.categories;
} else if (typeof body.categories === 'string' && body.categories.trim() !== '') {
  try { categories = JSON.parse(body.categories); } catch(e) {
    categories = body.categories.split(',').map(c => c.trim()).filter(Boolean);
  }
}
if (!Array.isArray(categories)) categories = [categories];

// Parse tags
let tags = [];
if (Array.isArray(body.tags)) {
  tags = body.tags;
} else if (typeof body.tags === 'string' && body.tags.trim() !== '') {
  try { tags = JSON.parse(body.tags); } catch(e) {
    tags = body.tags.split(',').map(t => t.trim()).filter(Boolean);
  }
}
if (!Array.isArray(tags)) tags = [tags];
tags = tags.map(t => typeof t === 'string' ? t.trim() : (t?.name || t)).filter(Boolean);

// Parse brand(s) — supports array ([12, 34]), JSON string ('[12, 34]'), comma string ('12, 34'), or single ID
let brandIds = [];
const rawBrand = body.brands || body.brand;

if (Array.isArray(rawBrand)) {
  brandIds = rawBrand.map(b => parseInt(b)).filter(id => !isNaN(id) && id > 0);
} else if (typeof rawBrand === 'string' && rawBrand.trim() !== '') {
  try {
    const parsed = JSON.parse(rawBrand);
    if (Array.isArray(parsed)) {
      brandIds = parsed.map(b => parseInt(b)).filter(id => !isNaN(id) && id > 0);
    } else if (!isNaN(parseInt(parsed)) && parseInt(parsed) > 0) {
      brandIds = [parseInt(parsed)];
    }
  } catch(e) {
    brandIds = rawBrand.split(',').map(b => parseInt(b.trim())).filter(id => !isNaN(id) && id > 0);
  }
} else if (typeof rawBrand === 'number' && rawBrand > 0) {
  brandIds = [rawBrand];
}

const brandId = brandIds.length > 0 ? brandIds[0] : null;

// --- Extract variable product specific fields ---
let attributes = [];
if (Array.isArray(body.attributes)) {
  attributes = body.attributes;
} else if (typeof body.attributes === 'string' && body.attributes.trim() !== '') {
  try { attributes = JSON.parse(body.attributes); } catch(e) { attributes = []; }
}

let variations = [];
if (Array.isArray(body.variations)) {
  variations = body.variations;
} else if (typeof body.variations === 'string' && body.variations.trim() !== '') {
  try { variations = JSON.parse(body.variations); } catch(e) { variations = []; }
}

// --- Validation ---
const errors = [];

if (!name) errors.push('Product name is required.');
if (!description) errors.push('Description is required.');

if (stockMode === 'track_quantity') {
  if (quantity === null || quantity === undefined || isNaN(quantity)) {
    errors.push('Quantity is required when tracking stock.');
  } else if (!Number.isInteger(quantity) || quantity <= 0) {
    errors.push('Quantity must be a positive integer (>= 1).');
  }
}

if (!binary.product_image) {
  errors.push('Product image is required.');
}

if (!Array.isArray(attributes) || attributes.length === 0) {
  errors.push('At least one attribute is required for a variable product.');
}

if (!Array.isArray(variations) || variations.length === 0) {
  errors.push('At least one variation is required for a variable product.');
}

if (variations.length > 0) {
  for (let i = 0; i < variations.length; i++) {
    const v = variations[i];
    if (!v.regular_price && v.regular_price !== '0' && v.regular_price !== 0) {
      errors.push(`Variation ${i + 1}: regular_price is required.`);
    }
    if (!v.attributes || !Array.isArray(v.attributes) || v.attributes.length === 0) {
      errors.push(`Variation ${i + 1}: at least one attribute selection is required.`);
    }
  }
}

if (errors.length > 0) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: errors.join(' ')
      }
    }
  }];
}

return [{
  json: {
    _valid: true,
    _formData: {
      name,
      description,
      regularPrice: regularPrice || null,
      salePrice: salePrice || null,
      sku: sku || null,
      stockMode,
      quantity,
      categories,
      tags,
      brandId,
      brandIds,
      galleryCount,
      attributes,
      variations
    }
  },
  binary: binary
}];

// Pass through validation error to the error response node
const items = $input.all();
return [{ json: items[0].json._error }];

// ============================================================
// PREPARE IMAGE UPLOAD ITEMS
// ============================================================
// Create output items for: 1. Main image, 2. Gallery images, 3. Variation images.
// Each item carries the binary under a 'file' key and metadata.
// n8n will process all items through the HTTP Request node.

const items = $input.all();
const binary = items[0].binary || {};
const formData = items[0].json._formData || {};
const galleryCount = formData.galleryCount || 0;
const variations = formData.variations || [];

const outputItems = [];

// 1. Main product image (always first)
if (binary.product_image) {
  outputItems.push({
    json: {
      _imageType: 'main',
      _imageIndex: 0,
      _formData: formData
    },
    binary: {
      file: binary.product_image
    }
  });
}

// 2. Gallery images (indexed as gallery_image_0, gallery_image_1, etc.)
for (let i = 0; i < galleryCount; i++) {
  const key = `gallery_image_${i}`;
  if (binary[key]) {
    outputItems.push({
      json: {
        _imageType: 'gallery',
        _galleryIndex: i,
        _formData: formData
      },
      binary: {
        file: binary[key]
      }
    });
  }
}

// 3. Child Variation images (indexed as variation_image_0, variation_image_1, etc.)
for (let i = 0; i < variations.length; i++) {
  const key = `variation_image_${i}`;
  if (binary[key]) {
    outputItems.push({
      json: {
        _imageType: 'variation',
        _variationIndex: i,
        _formData: formData
      },
      binary: {
        file: binary[key]
      }
    });
  }
}

return outputItems;

// ============================================================
// COLLECT ALL UPLOADED IMAGE IDs (MAIN, GALLERY, VARIATIONS)
// ============================================================
const uploadItems = $input.all();
const formData = $('Code - Validate Input').first().json._formData || {};
const prepItems = $('Code - Prepare Image Items').all() || [];

let mainImageId = null;
const galleryImageIds = [];
const variationImageMap = {}; // Map of { variationIndex: mediaId }

for (let i = 0; i < uploadItems.length; i++) {
  const data = uploadItems[i].json;
  const meta = prepItems[i]?.json || {};
  const mediaId = data.id;
  const imageType = meta._imageType || 'main';

  if (!mediaId) {
    continue;
  }

  if (imageType === 'main') {
    mainImageId = mediaId;
  } else if (imageType === 'gallery') {
    galleryImageIds.push(mediaId);
  } else if (imageType === 'variation') {
    if (meta._variationIndex !== undefined) {
      variationImageMap[meta._variationIndex] = mediaId;
    }
  }
}

if (!mainImageId) {
  return [{
    json: {
      _error: true,
      success: false,
      message: 'Failed to upload the main product image to WordPress Media: ' + (uploadItems[0]?.json?.message || 'Media upload error')
    }
  }];
}

// Build the images array for WooCommerce parent product (main image first)
const wcImages = [{ id: mainImageId }];
galleryImageIds.forEach(gid => wcImages.push({ id: gid }));

// Prepare tag items if tags exist
const tags = formData.tags || [];

if (tags.length > 0) {
  return tags.map((tagName, idx) => ({
    json: {
      _tagName: tagName,
      _tagIndex: idx,
      _wcImages: wcImages,
      _variationImageMap: variationImageMap,
      _hasTags: true
    }
  }));
} else {
  return [{
    json: {
      _wcImages: wcImages,
      _variationImageMap: variationImageMap,
      _hasTags: false,
      _tagIds: []
    }
  }];
}

// ============================================================
// AGGREGATE TAG IDs (HANDLES NEW & PRE-EXISTING TAGS)
// ============================================================
const items = $input.all();
const tagIds = [];

for (const item of items) {
  const data = item.json || {};

  // Case 1: Tag was freshly created
  if (data.id) {
    tagIds.push(parseInt(data.id));
    continue;
  }

  // Case 2: Tag already existed (term_exists in data.data.resource_id)
  if (data.data?.resource_id) {
    tagIds.push(parseInt(data.data.resource_id));
    continue;
  }

  // Case 3: Tag already existed but wrapped in n8n/Axios error object
  const rawStr = JSON.stringify(data);
  const match = rawStr.match(/resource_id[^0-9]+(\d+)/i);
  if (match && match[1]) {
    tagIds.push(parseInt(match[1]));
  }
}

const collectData = $('Code - Collect Image IDs & Prepare Tags').first().json || {};
const wcImages = collectData._wcImages || [];
const variationImageMap = collectData._variationImageMap || {};

return [{
  json: {
    _wcImages: wcImages,
    _variationImageMap: variationImageMap,
    _tagIds: tagIds
  }
}];

const collectData = $('Code - Collect Image IDs & Prepare Tags').first().json || {};
const wcImages = collectData._wcImages || [];
const variationImageMap = collectData._variationImageMap || {};
return [{
  json: {
    _wcImages: wcImages,
    _variationImageMap: variationImageMap,
    _tagIds: []
  }
}];

// ============================================================
// BUILD WOOCOMMERCE VARIABLE PRODUCT PAYLOAD
// ============================================================
const formData = $('Code - Validate Input').first().json._formData || {};
const tagData = $input.first()?.json || {};
const wcImages = tagData._wcImages || $('Code - Collect Image IDs & Prepare Tags').first().json._wcImages || [];
const variationImageMap = tagData._variationImageMap || $('Code - Collect Image IDs & Prepare Tags').first().json._variationImageMap || {};
const tagIds = tagData._tagIds || [];

// --- Base product payload ---
const product = {
  name: formData.name || 'Product',
  type: 'variable',
  description: formData.description || '',
  images: wcImages
};

// --- Optional: Regular price at parent level ---
if (formData.regularPrice && formData.regularPrice !== '' && formData.regularPrice !== null) {
  product.regular_price = formData.regularPrice.toString();
}

// --- Optional: Sale price at parent level ---
if (formData.salePrice && formData.salePrice !== '' && formData.salePrice !== null) {
  product.sale_price = formData.salePrice.toString();
}

// --- Optional: SKU ---
if (formData.sku && formData.sku !== '') {
  product.sku = formData.sku.toString();
}

// --- Categories ---
if (formData.categories && formData.categories.length > 0) {
  product.categories = formData.categories.map(id => ({ id: parseInt(id) }));
}

// --- Tags ---
if (tagIds.length > 0) {
  product.tags = tagIds.map(id => ({ id: parseInt(id) }));
}

// --- Stock logic (parent-level) ---
switch (formData.stockMode) {
  case 'in_stock':
    product.manage_stock = false;
    product.stock_status = 'instock';
    break;
  case 'out_of_stock':
    product.manage_stock = false;
    product.stock_status = 'outofstock';
    break;
  case 'track_quantity':
    product.manage_stock = true;
    if (formData.quantity !== null && formData.quantity !== undefined) {
      product.stock_quantity = parseInt(formData.quantity);
    }
    break;
  default:
    product.manage_stock = false;
    product.stock_status = 'instock';
}

// --- Attributes (variable product specific) ---
if (formData.attributes && formData.attributes.length > 0) {
  product.attributes = formData.attributes.map(attr => ({
    id: attr.id ? parseInt(attr.id) : undefined,
    name: attr.name || '',
    options: attr.options || [],
    variation: attr.variation !== false,
    visible: attr.visible !== false
  }));
}

return [{
  json: {
    _productPayload: product,
    _brandId: formData.brandId || null,
    _brandIds: formData.brandIds || (formData.brandId ? [formData.brandId] : []),
    _variations: formData.variations || [],
    _variationImageMap: variationImageMap
  }
}];

// ============================================================
// PROCESS PRODUCT CREATION RESULT & PREPARE VARIATIONS
// ============================================================
const items = $input.all();
const data = items[0]?.json || {};
const formData = $('Code - Validate Input').first().json._formData || {};
const buildData = $('Code - Build Variable Product Payload').first().json || {};
const variationsData = buildData._variations || [];
const variationImageMap = buildData._variationImageMap || {};
const brandIds = buildData._brandIds || formData.brandIds || [];

// Check if product was created successfully
if (!data.id) {
  return [{
    json: {
      _error: true,
      success: false,
      message: 'Failed to create variable product: ' + (data.message || JSON.stringify(data))
    }
  }];
}

return [{
  json: {
    _productId: data.id,
    _productName: data.name || formData.name || 'Product',
    _brandId: formData.brandId || (brandIds[0] || null),
    _brandIds: brandIds,
    _productCreated: true,
    _variations: variationsData,
    _variationImageMap: variationImageMap
  }
}];

// ============================================================
// PREPARE VARIATION BATCH PAYLOAD
// ============================================================
// Instead of creating N output items (N API calls),
// build a single batch payload for WooCommerce's batch endpoint.
// POST /wc/v3/products/{id}/variations/batch { create: [...] }
// Reduces N API calls to 1 — dramatically lowers server load.

const items = $input.all();
const productId = items[0].json._productId;
const productName = items[0].json._productName;
const brandId = items[0].json._brandId;
const brandIds = items[0].json._brandIds || (brandId ? [brandId] : []);
const variations = items[0].json._variations || [];
const variationImageMap = items[0].json._variationImageMap || {};

if (variations.length === 0) {
  return [{
    json: {
      _productId: productId,
      _productName: productName,
      _brandId: brandId,
      _brandIds: brandIds,
      _noVariations: true,
      _batchPayload: null
    }
  }];
}

const batchCreate = variations.map((variation, idx) => {
  const payload = {
    attributes: (variation.attributes || []).map(attr => ({
      id: attr.id ? parseInt(attr.id) : undefined,
      name: attr.name || '',
      option: attr.option || ''
    }))
  };

  // Attach Variation Specific Image if uploaded
  if (variationImageMap[idx]) {
    payload.image = { id: parseInt(variationImageMap[idx]) };
  } else if (variation.image_id) {
    payload.image = { id: parseInt(variation.image_id) };
  }

  // Regular price (required on each variation)
  if (variation.regular_price !== undefined && variation.regular_price !== null) {
    payload.regular_price = variation.regular_price.toString();
  }

  // Sale price (optional)
  if (variation.sale_price && variation.sale_price !== '' && variation.sale_price !== null) {
    payload.sale_price = variation.sale_price.toString();
  }

  // SKU (optional)
  if (variation.sku && variation.sku !== '') {
    payload.sku = variation.sku.toString();
  }

  // Flags: virtual, downloadable, status
  if (variation.virtual !== undefined) payload.virtual = Boolean(variation.virtual);
  if (variation.downloadable !== undefined) payload.downloadable = Boolean(variation.downloadable);
  if (variation.status) payload.status = variation.status;

  // Weight & Dimensions
  if (variation.weight) payload.weight = variation.weight.toString();
  if (variation.dimensions && typeof variation.dimensions === 'object') {
    payload.dimensions = {
      length: (variation.dimensions.length || '').toString(),
      width: (variation.dimensions.width || '').toString(),
      height: (variation.dimensions.height || '').toString()
    };
  }

  // Description
  if (variation.description) payload.description = variation.description.toString();

  // GTIN / UPC / EAN metadata
  if (variation.gtin || variation.upc || variation.ean) {
    payload.meta_data = payload.meta_data || [];
    if (variation.gtin) payload.meta_data.push({ key: '_gtin', value: variation.gtin });
    if (variation.upc) payload.meta_data.push({ key: '_upc', value: variation.upc });
    if (variation.ean) payload.meta_data.push({ key: '_ean', value: variation.ean });
  }

  // Stock management
  const manageStock = Boolean(variation.manage_stock);
  payload.manage_stock = manageStock;
  if (manageStock) {
    if (variation.stock_quantity !== null && variation.stock_quantity !== undefined && variation.stock_quantity !== '') {
      payload.stock_quantity = parseInt(variation.stock_quantity);
    }
    payload.stock_status = (variation.stock_quantity > 0) ? 'instock' : (variation.stock_status || 'instock');
  } else {
    payload.stock_status = variation.stock_status || 'instock';
  }

  return payload;
});

return [{
  json: {
    _productId: productId,
    _productName: productName,
    _brandId: brandId,
    _brandIds: brandIds,
    _noVariations: false,
    _batchPayload: { create: batchCreate }
  }
}];

// ============================================================
// CHECK BATCH VARIATIONS RESULT & PREPARE BRAND ASSIGNMENT
// ============================================================
// Parses WooCommerce batch endpoint response.
// Batch response format: { create: [...created_variation_objects] }

const items = $input.all();
const data = items[0]?.json || {};
const prepItem = $('Code - Prepare Variation Batch').first()?.json || {};
const productId = prepItem._productId;
const productName = prepItem._productName;
const brandId = prepItem._brandId;
const brandIds = prepItem._brandIds || (brandId ? [brandId] : []);

const createdVariations = [];
const failedVariations = [];

// Batch endpoint returns { create: [...results] }
const batchResults = data.create || [];

for (let i = 0; i < batchResults.length; i++) {
  const result = batchResults[i];
  if (result.id) {
    createdVariations.push({
      id: result.id,
      attributes: result.attributes || [],
      regular_price: result.regular_price || '',
      sale_price: result.sale_price || ''
    });
  } else {
    failedVariations.push({
      index: i,
      error: result.error?.message || result.message || 'Unknown error'
    });
  }
}

return [{
  json: {
    _productId: productId,
    _productName: productName,
    _brandId: brandId,
    _brandIds: brandIds,
    _hasBrand: brandIds.length > 0,
    _createdVariations: createdVariations,
    _failedVariations: failedVariations,
    _variationsOk: createdVariations.length > 0
  }
}];

const productId = $('Code - Check Variations Result').first()?.json._productId;
const productName = $('Code - Check Variations Result').first()?.json._productName;
const createdVariations = $('Code - Check Variations Result').first()?.json._createdVariations || [];
const failedVariations = $('Code - Check Variations Result').first()?.json._failedVariations || [];

return [{
  json: {
    success: true,
    message: 'Variable product created successfully!',
    product: {
      id: productId || null,
      name: productName || 'Product',
      type: 'variable',
      brand_assigned: true,
      variations_created: createdVariations.length,
      variations_failed: failedVariations.length,
      variations: createdVariations,
      failed_variations: failedVariations
    }
  }
}];

const productId = $('Code - Check Variations Result').first()?.json._productId;
const productName = $('Code - Check Variations Result').first()?.json._productName;
const createdVariations = $('Code - Check Variations Result').first()?.json._createdVariations || [];
const failedVariations = $('Code - Check Variations Result').first()?.json._failedVariations || [];

return [{
  json: {
    success: true,
    message: 'Variable product created successfully!',
    product: {
      id: productId || null,
      name: productName || 'Product',
      type: 'variable',
      brand_assigned: false,
      variations_created: createdVariations.length,
      variations_failed: failedVariations.length,
      variations: createdVariations,
      failed_variations: failedVariations
    }
  }
}];
